{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to stage-1 choices.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a bonus to the stage-1 action chosen on the previous trial, promoting perseveration regardless of reward.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "stick_var = np.zeros(2)\n        if trial > 0:\n            stick_var[action_1[trial - 1]] = 1.0\n            \n        exp_q1 = np.exp(beta * q_stage1_net + stickiness * stick_var)",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Decays the values of all unchosen actions at both stages toward zero.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[1 - action_1[trial]] *= (1 - decay)\n...\nq_stage2_mf[state_idx, 1 - action_2[trial]] *= (1 - decay)\n        q_stage2_mf[1 - state_idx, 0] *= (1 - decay)\n        q_stage2_mf[1 - state_idx, 1] *= (1 - decay)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free value using the stage-2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambda_",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lambda_ * delta_stage2  # eligibility trace update",
      "expressible_in_slots": true
    }
  ]
}
